package com.bank.counter;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class CounterDemo {
    private static final Logger log = Logger.getLogger(CounterDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));
        log.info(() -> "Account under test: " + rajesh.getAccountId());

        SettlementCounterService svc = new SettlementCounterService();

        // 1) Why MAX_VALUE + 1 is negative — silent wraparound.
        log.warning(() -> "Integer.MAX_VALUE = " + Integer.MAX_VALUE
                + ", MAX_VALUE + 1 = " + (Integer.MAX_VALUE + 1) + " (wrapped to MIN_VALUE!)");

        // 2) Silent int overflow accumulating paise.
        int unsafe = svc.addPaiseUnsafe(2_000_000_000, 500_000_000);
        log.warning(() -> "Unsafe int total = " + unsafe + " (SILENTLY wrong/negative)");

        // 3) Safe long accumulator — no overflow for realistic volumes.
        long safe = svc.addPaiseSafe(2_000_000_000L, 500_000_000L);
        log.info(() -> "Safe long total = " + safe + " (correct)");

        // 4) multiplyExact catches a capacity overflow loudly.
        try {
            int cap = svc.requiredBufferSize(100_000, 100_000);
            log.info(() -> "Buffer size = " + cap);
        } catch (ArithmeticException e) {
            log.severe(() -> "Capacity overflow detected safely: " + e.getMessage());
        }

        // 5) toIntExact fails loudly if a long will not fit an int report field.
        try {
            int report = svc.toReportInt(5_000_000_000L);
            log.info(() -> "Report int = " + report);
        } catch (ArithmeticException e) {
            log.severe(() -> "toIntExact rejected oversized value: " + e.getMessage());
        }
    }
}

