class SettlementCounterService {
    private static final Logger log = Logger.getLogger(SettlementCounterService.class.getName());

    // DANGEROUS: silent wraparound when the sum exceeds int range.
    int addPaiseUnsafe(int running, int delta) {
        return running + delta;   // may silently wrap to a negative number
    }

    // SAFE: a 64-bit long holds any realistic daily paise figure.
    long addPaiseSafe(long running, long delta) {
        return Math.addExact(running, delta);  // still throws if even long overflows
    }

    // SAFE capacity math: throws ArithmeticException instead of silent wrong size.
    int requiredBufferSize(int batches, int perBatch) {
        return Math.multiplyExact(batches, perBatch);
    }

    // SAFE narrowing: throws if the long value does not fit an int.
    int toReportInt(long value) {
        return Math.toIntExact(value);
    }
}

